CREATE TABLE [purchase].[PurchaseSeries]([PurchaseSeriesId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_PurchaseSeries_Id] DEFAULT NEWSEQUENTIALID(),[SeriesCode] NVARCHAR(20) NOT NULL,[Prefix] NVARCHAR(20) NOT NULL,[NextNumber] BIGINT NOT NULL CONSTRAINT [DF_PurchaseSeries_Next] DEFAULT 1,[NumberLength] INT NOT NULL CONSTRAINT [DF_PurchaseSeries_Length] DEFAULT 6,[IsDefault] BIT NOT NULL CONSTRAINT [DF_PurchaseSeries_Default] DEFAULT 0,[IsActive] BIT NOT NULL CONSTRAINT [DF_PurchaseSeries_Active] DEFAULT 1,[RowVersion] ROWVERSION NOT NULL,CONSTRAINT [PK_PurchaseSeries] PRIMARY KEY([PurchaseSeriesId]),CONSTRAINT [UQ_PurchaseSeries_Code] UNIQUE([SeriesCode]),CONSTRAINT [CK_PurchaseSeries_Next] CHECK([NextNumber]>0),CONSTRAINT [CK_PurchaseSeries_Length] CHECK([NumberLength] BETWEEN 3 AND 12));
GO
CREATE UNIQUE INDEX [UX_PurchaseSeries_Default] ON [purchase].[PurchaseSeries]([IsDefault]) WHERE [IsDefault]=1 AND [IsActive]=1;
